// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(uint256 depositAmount, uint8 numWithdrawals, address actor) public {
        vm.assume(actor != address(0) && actor != address(this));
        depositAmount = bound(depositAmount, 1 ether, 100 ether);
        numWithdrawals = uint8(bound(numWithdrawals, 1, 5));

        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.addToBalance{value: depositAmount}();

        uint256 initialBalance = c.getBalance(actor);
        assertEq(initialBalance, depositAmount);

        uint256 totalWithdrawn = 0;
        address payable actorPayable = payable(actor);
        uint256 initialActorBal = actorPayable.balance;

        for (uint8 i = 0; i < numWithdrawals; i++) {
            vm.prank(actor);
            (bool ok, bytes memory ret) = address(c).call(abi.encodeWithSelector(Reentrance.withdrawBalance.selector));
            if (ok) {
                uint256 delta = actorPayable.balance - initialActorBal;
                totalWithdrawn += delta;
                initialActorBal = actorPayable.balance;
            } else {
                break;
            }
        }

        uint256 finalBalance = c.getBalance(actor);
        assertTrue(finalBalance == depositAmount - totalWithdrawn);
    }
}
